-- Daily Dew Shiloh July 2026 seed.
-- Run this after supabase-schema.sql in the Supabase SQL Editor.
begin;

insert into public.editions (slug, title, theme, month, year, language, status, introduction)
values (
  'shiloh-july-2026',
  'Shiloh',
  'Genesis 1:28 Era',
  7, 2026, 'en', 'draft',
  'The July edition journeys through the blessing, fruitfulness, multiplication, restoration, and dominion of Genesis 1:28.'
)
on conflict (slug) do update set updated_at = now();

insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 1, 'Wondersday 1st', 'The Blessing Before The Command', 'And God blessed them, and God said unto them, Be fruitful, and multiply, and replenish the earth, and subdue it: and have dominion over the fish of the sea, and over the fowl of the air, and over every living thing that moveth upon the earth. – Genesis 1:28 KJV', 'One of the greatest revelations in scripture is that God blessed man before He gave him an assignment. The first thing Adam received was not work, responsibility, or authority, it was the blessing. This blessing was heaven''s empowerment to succeed in every divine assignment. Fruitfulness, multiplication, replenishment, subduing, and dominion are not human achievements; they are manifestations of God''s blessing at work in a yielded life. Every believer in Christ has been called to function from this position of divine empowerment rather than human effort. When you understand that you are already blessed in Christ, you stop striving for acceptance and begin manifesting God''s original plan. Fellow Labourer in Christ, refuse to approach this month with a mentality of lack, fear, or limitation. You are carrying the blessing of God, and that blessing distinguishes you wherever you go. Let every decision, prayer, and action this month flow from the consciousness that heaven has already spoken well concerning you. As you remain connected to God through obedience, prayer, and His Word, the blessing upon your life will produce visible fruit, supernatural increase, divine restoration, victory over eve ry opposition, and unquestionable dominion. This is your season to manifest God''s original intention for your life. Great Grace!', '["Ephesians 1:3", "Deuteronomy 28:1 –13", "Psalm 1:1 –3", "2 Corinthians 9:8"]'::jsonb, 'God''s blessing is the divine empowerment that makes His commands possible.', 'I am blessed by God and empowered for fruitfulness. I shall multiply in grace, wisdom, influence, and resources. Every loss is restored, every opposition is subdued, and I walk in dominion through Christ Jesus. This month, I manifest God''s original purpose for my life. Amen!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 2, 'Triumphday 2nd', 'The Mystery Of Fruitfulness', 'And God blessed them, and God said unto them, Be fruitful… – Genesis 1:28 KJV', 'Fruitfulness is the first expectation God placed upon humanity. Notice that before God spoke of multiplication, replenishment, or dominion, He first commanded man to be fruitful. This is because multiplication is impossible without fruitfulness. In scripture, fruitfulness is more than having children or possessing material abundance – It is the ability to consistently produce results that glorify God. A fruitful believer produces the fruit of the Spirit (ref: Galatians 5:22-23), wins souls (ref: John 15:16), grows in wisdom (ref: Proverbs 3:13 -18), influences generations, and leaves behind a godly legacy. Fruitfulness is the visible evidence that divine life is actively flowing through a believer. Fellow Labourer in Christ, never mistake activity for fruitfulness. Many are busy, yet they produce nothing of eternal value. God is not impressed by motion; He is pleased by results that originate from His Spirit. Examine your life today, is your prayer life fruitful? Is your ministry fruitful? Is your business, family, studies, or career producing God -honouring results? Whatever remains connected to Christ cannot remain barren. Therefore, remain rooted in His presence, abide in His Word, and yield yourself to the Holy Spirit. I pray for you; the life of God within you possesses everything necessary to make you fruitful in every dimension of life in the name of Jesus. Great Grace!', '["John 15:1–8", "Psalm 92:12–15", "Colossians 1:10", "Galatians 5:22–23"]'::jsonb, 'God measures your life by fruitfulness, not by busyness.', 'I refuse every form of barrenness. I am fruitful spiritually, mentally, financially, ministerial, and physically. Everywhere I go, I produce lasting results that glorify God. My life is a testimony of divine productivity, in Jesus’ Name. Amen!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 3, 'Faithday 3rd', 'The Law Of Multiplication', 'And God blessed them, and God said unto them, Be fruitful, and multiply... – Genesis 1:28', 'God never intended His blessings to remain at the level of addition. The Kingdom of God operates by multiplication. A single seed produces a harvest. One disciple raises many disciples. One anointed man equips many labourers. Throughout scripture, God consistently demonstrates His nature through multiplication. He multiplied Abraham into nations, multiplied Israel in Egypt despite oppression, multiplied the widow''s oil, multiplied five loaves to feed thousands, and multiplied grace in the New Testament Churc h. Whenever God is involved, increase becomes inevitable. Multiplication is the supernatural enlargement of what has already become fruitful. Fellow Labourer in Christ, never despise what God has already placed in your hands. Heaven does not multiply what is ignored; it multiplies what is surrendered. The little gift, the small opportunity, the humble beginning, and the hidden season are all raw materials for divine multiplication. Faithfulness attracts increase. Gratitude preserves increase. Obedience accelerates increase. Refuse to compare your beginning with another person''s harvest. I pray for you; as you continue serving diligently, the God who multiplies seeds will multiply your influence, resources, wisdom, opportunities, and impact upon the earth in Jesus'' name. Great Grace!', '["Matthew 25:14–30", "Mark 6:37–44", "2 Corinthians 9:10", "Acts 6:7"]'::jsonb, 'God multiplies what is faithfully surrendered to Him.', 'The grace of multiplication rests upon my life. Every good thing God has planted within me shall increase beyond human expectation. I multiply in wisdom, influence, favour, resources, and kingdom impact, in Jesus'' Name. Hallelujah!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 4, 'Sabbathday 4th', 'Replenish The Wasted Places', '‘And I will restore to you the years that the locust hath eaten, the cankerworm, and the caterpillar, and the palmerworm… – Joel 2:25', 'The command to replenish the earth reveals that God’s nature is restorative. To replenish means to refill, restore, recover, and bring back to fullness what has become empty. Sin introduced loss into creation, but redemption introduced restoration. Throughout scripture, God reveals Himself as the restorer of broken destinies, wasted years, shattered hopes, and forgotten dreams. He restored Job’s fortunes, revived Naomi’s household, restored Peter after failure, and raised dry bones into a mighty army. Our God never abandons empty places; He fills them again with His glory. Fellow Labourer in Christ, perhaps you have experienced delays, disappointments, financial setbacks, spiritual dryness, or missed opportunities. The God who commanded replenishment has not forgotten you. He specializes in restoring what men consider irrecoverable. Refuse to dwell on yesterday’s losses. Lift up your voice for a minute and call on the God of restoration. I pray for you; as you believe in His promises and align yourself to His will, supernatural recovery is yours throughout this month. Every s eason surrendered to Him becomes a testimony for you. What took years to lose will be restored by divine intervention in a moment in the name of Jesus. Great Grace!', '["Joel 2:21–27", "Isaiah 61:7", "Job 42:10", "Psalm 126:1–6"]'::jsonb, 'God’s restoration is never merely replacement; it is divine compensation.', 'Every wasted season is restored. Every lost opportunity returns by divine mercy. The Lord replenishes my strength, resources, joy, peace, relationships, and purpose. I recover all, in Jesus’ Name. Glory!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 5, 'Sacredday 5th', 'The Mandate to Subdue', '…Replenish the earth, and subdue it: and have dominion... – Genesis 1:28', 'The word subdue means to bring under control, to conquer, to overcome resistance, and to establish divine order where chaos exists. God never promised Adam a resistance -free earth. Instead, He empowered him to overcome every resistance he would encounter. Likewise, every believer will face opposition, whether from the flesh, the world, or the kingdom of darkness, but we have been equipped with divine authority through Christ. To subdue is not to dominate people but to overcome every force that seeks to hinder God''s ordination in our lives. Through prayer, faith, obedience, and the authority of God''s Word, every mountain can be brought low. Fellow Labourer in Christ, never surrender the territory that God has assigned to you. Whether it is your spiritual life, family, ministry, career, health, or calling, refuse to permit the enemy to occupy what belongs to the Lord. Every challenge before you is an opportunity to demonstrate the victory already secured through Christ. Do not negotiate with fear, compromise with sin, or retreat because of opposition. Rise in the authority of your heavenly position. I pray for you; as you walk in obedience and exercise your God-given authority, every contradicting voice shall be silenced, every obstacle shall bow, and every resistance shall give way before the power of God in Jesus'' name. Great Grace!', '["Luke 10:19", "Joshua 1:3–9", "Romans 8:37", "1 John 4:4"]'::jsonb, 'Every divine assignment carries sufficient grace to overcome every opposition.', 'I subdue every work of darkness assigned against my life. By the authority of Jesus Christ, every opposition bows before me. I walk in total victory, I possess my inheritance, and I establish God''s Kingdom wherever He sends me. Hallelujah!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 6, 'Mercyday 6th', 'The Life of Dominion', '…and have dominion over the fish of the sea, and over the fowl of the air, and over every living thing that moveth upon the earth. – Genesis 1:28', 'Dominion is the climax of God’s original mandate to mankind. After blessing man, commanding fruitfulness, multiplication, replenishment, and subduing, God crowned it with dominion. Dominion is not oppression; it is righteousness stewardship under the authority of God. It is the ability to govern circumstances without being governed by them. Before the fall, Adam was not intimidated by creation because he carried the authority of the Creator. He named the animals, cultivated the garden, and functioned as God’s representative on the earth. Through the finished work of Christ the last Adam; that dominion has been restored to every believer. Dominion is therefore the practical expression of Christ’s victory manifested through His Church and the saints. Fellow Labourer in Christ, refuse to live beneath your spiritual position. You were not redeemed merely to escape hell; you were redeemed to represent Heaven. A believer walking in dominion does not allow fear to dictate decisions, sin to control his life, or the systems of this world to define his identity. Dominion begins within before it is manifested without. A man who cannot govern his appetite cannot govern territories. A woman who cannot rule over anger cannot effectively rule over circumstances. Allow the Holy Spirit to establish His government in your heart, and His authority will naturally flow through your life. I pray for you; in this month, wherever darkness has attempted to reign, let the light of Christ in you establish the government of Heave n in the name of Jesus. Great Grace!', '["Romans 5:17", "Luke 10:19", "Psalm 8:4–8", "Revelation 5:10"]'::jsonb, 'True dominion begins with self -government under the government of God.', 'I walk in the dominion of Christ. Sin shall not rule over me. Fear shall not master me. I reign over circumstances through the authority of Jesus Christ. Every area of my life reflects the government of Heaven. I am more than a conqueror. Amen!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 7, 'Truthday 7th', 'Abide to Abound', 'I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing. – John 15:5', 'Every branch has only one responsibility, to remain connected to the vine. It does not struggle to produce fruits; it simply abides, and fruits becomes the natural outcome of that relationship. This is one of the greatest mysteries of the Kingdom. Many believers spend their energy trying to manufacture results instead of cultivating intimacy with Christ. Fruitfulness is never produced by human effort alone; it is the overflow of divine life. The sap that nourishes the branch is invisible from outer view, yet its evidence becomes visible in the fruit. Likewise, our secret fellowship with God eventually becomes public manifestation. Prayer, meditation on the Word, worship, and obedience are not religious activities; they are the channels through which the life of Christ continually flows into the believer. Fellow Labourer in Christ, if you desire unusual results, deepen your communion with God. Public victories are born from private encounters. Do not become so occupied with ministry that you neglect the Master. Do not pursue gifts while abandoning the Giver. There is no substitute for daily fellowship with the Holy Spirit. The believer who abides in Christ carries a freshness that the world cannot explain. Even in seasons of drought, he remains fruitful because his source is not earthly but heavenly. I pray for you; your greatest pursuit this month will be intimacy with God, and as you do so every other blessing will become the fruit of that relationship in Jesus’ name. Great Grace!', '["Psalm 1:1 –3", "Jeremiah 17:7 –8", "Colossians 2:6–7", "Ephesians 3:16–19"]'::jsonb, 'The secret place is the birthplace of public fruitfulness.', 'I abide in Christ continually. His life flows through me, and I bring forth lasting fruits. I shall never be spiritually dry, emotionally empty, or physically barren. My life overflows with the abundance of God’s presence. Hallelujah!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 8, 'Wondersday 8th', 'The Power of the Blessing', 'The blessing of the LORD, it maketh rich, and he addeth no sorrow with it. – Proverbs 10:22', 'The blessing of God is more than kind words or good wishes; it is a spiritual force released by God that empowers a person to prosper according to His purpose. In Genesis 1:28, God did not merely encourage Adam, He blessed him. That blessing became the divine ability to fulfil every assignment Heaven had given. Throughout Scripture, we see that wherever the blessing of God rested, impossible things became possible. Abraham became the father of nations, Isaac prospered during famine, Joseph rul ed in a foreign land, and David rose from shepherd to king. The blessing distinguishes ordinary people for extraordinary exploits because it carries the favour, presence, and power of God. Fellow Labourer in Christ, never underestimate what rests upon your life because you belong to Christ. The blessing is not determined by your location, background, economy, or family history. It flows from your covenant relationship with God. Even when circumstances appear contrary, the blessing is working behind the scenes to align events in your favour. Therefore, refuse to speak words that contradict the blessing. Declare God’s promises over your life daily. Walk in obedience, maintain a thankful heart, and expect divine interventions. I pray for you; let the blessing of God open doors that qualifications cannot open, preserve what human wisdom cannot preserve, and establish what human strength cannot establish in Jesus’ name. Great Grace!', '["Genesis 12:1–3", "Deuteronomy 28:1–14", "Ephesians 1:3", "Galatians 3:13–14"]'::jsonb, 'The blessing is Heaven’s empowerment for earthly accomplishment.', 'The blessing of the Lord is evident upon my life. I prosper without sorrow. I am favoured, preserved, distinguished and empowered to fulfil my divine assignment. Everywhere I go, the blessing speaks on my behalf. Glory!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 9, 'Triumphday 9th', 'From Seed to Harvest', 'In the morning sow thy seed, and in the evening withhold not thine hand: for thou knowest not whether shall prosper, either this or that, or whether they both shall be alike good. – Ecclesiastes 11:6', 'God’s Kingdom operates on the principle of seedtime and harvest. Every harvest begins with a seed, and every seed carries within it the potential for multiplication. This principle governs every aspect of life. As we saw in the month of seeds and investment, our words are seeds, our actions are seeds, our prayers are seeds, our giving is seed, and even our character is continually sowing into our future. No farmer expects a harvest without planting, and no believer should expect a fruitful life while neglect ing the discipline of sowing into the Kingdom. The remarkable thing about God’s economy is that He often hides great destinies inside small beginnings. A single seed may appear insignificant, but under God’s blessing it can become a mighty forest. Fellow Labourer in Christ, do not become weary because your harvest has not yet appeared. Every seed has an appointed season of manifestation. Continue sowing righteousness, kindness, generosity, excellence, prayer, and faithfulness. Resist the temptation to abandon your field because of temporary delays. The God who watches over His Word also watches over every seed sown in obedience. In due season, what has been hidden beneath the soil will break forth with undeniable increase. As you harvest fruits this month, do not forget to intentional sow more seeds for the harvest of tomorrow is determined by the seeds you plant today. Great Grace!', '["Genesis 8:22", "Galatians 6:7 –9", "2 Corinthians 9:6 –11", "Mark 4:26–29"]'::jsonb, 'Your future harvest is hidden inside today’s faithful seed.', 'Every good seed I have sown shall produce an abundant harvest. I shall not labour in vain. My obedience, prayers, sacrifices, and service shall yield multiplied returns according to God’s perfect will. Amen!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 10, 'Faithday 10th', 'Created To Cultivate', 'And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. - Genesis 2:15 KJV', 'Before sin entered the world, work already existed. This reveals that work is not a curse; it is a divine responsibility. Adam was placed in Eden not merely to enjoy its beauty but to cultivate and preserve it. The blessing of Genesis 1:28 was never intended to promote laziness. God''s pattern is blessing followed by responsibility, favour followed by stewardship, and increase followed by accountability. The Garden of Eden represents every assignment, opportunity, relationship, ministry, busi ness, career, and gift entrusted to us by God. Nothing flourishes without cultivation. Even the most fertile ground becomes overgrown when neglected. Likewise, every divine promise requires diligent cooperation with God. Fellow Labourer in Christ, ask yourself, " what garden has God entrusted to me?" It may be your family, your ministry, your profession, your business, your education, or the spiritual gifts deposited within you. Whatever God has placed in your hands deserves your excellence. Never pray for enlargement while neglecting your present assignment. Many seek another vineyard while abandoning the one already entrusted to them. Faithfulness in little is God''s pathway to much. Cultivate your prayer life. Develop your gifts. Improve your skills. Guard your cha racter. Protect your relationships. As you faithfully tend what God has given you, He will enlarge your borders and entrust you with greater responsibilities. Great Grace!', '["Proverbs 22:29", "Matthew 25:21", "Luke 16:10", "Colossians 3:23–24"]'::jsonb, 'God blesses what you cultivate, not what you neglect.', 'I receive grace to faithfully cultivate every assignment God has committed into my hands. I reject laziness, negligence, and mediocrity. Through diligence and the blessing of God, my life shall continually flourish, in Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 11, 'Sabbathday 11th', 'The Blessing Of Capacity', 'Enlarge the place of thy tent, and let them stretch forth the curtains of thine habitations: spare not, lengthen thy cords, and strengthen thy stakes; For thou shalt break forth on the right hand and on the left... - Isaiah 54:2-3 KJV', 'God never pours new wine into old wineskins. Before He enlarges your harvest, He enlarges your capacity. Capacity is your ability to receive, contain, manage, and sustain what God desires to release into your life. Many believers pray for increase but resist the process of growth. Yet God is more interested in preparing the vessel than merely releasing the blessing.\n\nAbraham''s capacity was enlarged through years of walking with God. Joseph''s leadership was forged in slavery and prison before the palace. David''s heart was prepared in lonely fields before the throne. Heaven enlarges the man before enlarging his territory. Fellow Labourer in Christ, do not despise seasons of preparation. The trials, corrections, teachings, and disciplines you are presently experiencing are enlarging your spiritual capacity.\n\nEvery book you read, every lesson you learn, every act of obedience, every sacrifice, and every prayer is stretching your ability to carry greater glory. Refuse to settle for yesterday''s level of understanding. Grow in wisdom. Grow in faith. Grow in character. Grow in competence. The greater your capacity, the greater your usefulness in the Kingdom. God desires to entrust much to those who have become mature enough to carry it without pride or compromise. Great Grace!', '["Isaiah 54:2–3", "Luke 12:48", "2 Timothy 2:20–21", "Ephesians 3:20"]'::jsonb, 'Your capacity determines the measure of your stewardship.', 'Lord, enlarge my capacity. Expand my faith, my wisdom, my understanding, and my influence. Prepare me for greater assignments and greater manifestations of Your glory. I shall not break under the weight of my next level, in Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 12, 'Sacredday 12th', 'The Mystery Of Kingdom Influence', 'Ye are the salt of the earth... Ye are the light of the world. A city that is set on an hill cannot be hid. - Mathew 5:13-15 KJV', 'God''s command to "replenish the earth" and "have dominion" was never confined to occupying physical space; it also meant influencing culture with Heaven''s values. Salt preserves, seasons, and prevents corruption. Light reveals, guides, and dispels darkness. Jesus intentionally used these two illustrations because they describe the believer''s assignment in the world. We are not called to escape society but to transform it. Dominion is not measured by titles or positions; it is measured by influence. Wherever God''s people carry His presence, righteousness should replace corruption, hope should overcome despair, and truth should silence deception. One Joseph preserved an entire civilization. One Esther rescued a nation. One Daniel changed the policies of kingdom s because they carried the influence of Heaven. Fellow Labourer in Christ, never underestimate the impact your life can make. You may be the only Bible someone ever reads. Your integrity may open doors that preaching alone cannot. Your excellence at work may become the platform through which Christ is r evealed. Let your speech carry grace. Let your conduct reflect holiness. Let your decisions reveal wisdom. Refuse to blend into the darkness around you. Instead, become a visible expression of God''s Kingdom wherever He has planted you. When believers walk in righteousness and excellence, they become irresistible witnesses of God''s glory. Great Grace!', '["Daniel 6:1–5", "Philippians 2:14–16", "1 Peter 2:9–10", "Romans 12:2"]'::jsonb, 'Influence is dominion expressed through godly character.', 'I am the salt of the earth and the light of the world. Through my life, God''s wisdom, righteousness, and glory are revealed. I influence my generation for Christ and advance His Kingdom wherever I go. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 13, 'Mercyday 13th', 'The Law Of Increase', 'Of the increase of his government and peace there shall be no end, upon the throne of David, and upon his kingdom, to order it, and to establish it with judgment and with justice from henceforth even forever. - Isaiah 9:7 KJV', 'Increase is one of the undeniable characteristics of God''s Kingdom. Wherever God reigns, stagnation is not permitted. The Kingdom is continually advancing, continually expanding, and continually manifesting greater glory. This is why Genesis 1:28 commands us to "multiply." God is not merely interested in maintaining what He has already done; He delights in taking His people from glory to glory, strength to strength, and faith to faith.\n\nThe law of increase is rooted in God''s own nature. He created one man and produced nations. He planted one garden and intended it to replenish the earth. He anointed twelve disciples who turned the world upside down. Every genuine encounter with God should leave a believer growing in wisdom, character, influence, and spiritual authority.\n\nFellow Labourer in Christ, reject every mentality of stagnation. Refuse to become comfortable with yesterday''s victories while neglecting today''s opportunities. Growth is intentional. Your prayer life should increase. Your knowledge of Scripture should deepen. Your love for people should mature. Your excellence in service should improve. The greatest enemy of tomorrow''s increase is satisfaction with yesterday''s success. Keep stretching your faith. Keep learning. Keep serving. Keep believing. As you remain yielded to the Holy Spirit, He will continually enlarge your vision and empower you for greater assignments. Your latter days shall be greater than your former because the God you serve is the God of increase. Great Grace!', '["Proverbs 4:18", "2 Corinthians 3:18", "Psalm 115:14–15", "Acts 2:47"]'::jsonb, 'Where God rules, increase becomes a lifestyle.', 'I reject stagnation in every area of my life. I increase in grace, wisdom, favour, influence, resources, and spiritual authority. From this day forward, my path shines brighter and brighter unto the perfect day. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 14, 'Truthday 14th', 'The Mystery Of Divine Order', 'Let all things be done decently and in order." - 1 Corinthians 14:40 KJV', 'Before God commanded man to subdue the earth, He first demonstrated the principle of divine order in creation. Genesis chapter one reveals that nothing God created was random. Light came before vegetation. The heavens were arranged before the stars were placed in them. The earth was prepared before man was introduced. God established systems before introducing those who would function within them. This teaches us that dominion flourishes where order exists. Disorder weakens productivity, but order multiplies efficiency. Heaven operates through divine order, and every believer who desires lasting fruitfulness must embrace God''s systems. The Holy Spirit is not the author of confusion but of peace, clarity, and divine arrangement. Fellow Labourer in Christ, examine the systems of your life. Is there order in your prayer life? Is your time properly managed? Are your finances governed by biblical principles? Is your home built on godly values? Many people pray for breakthrough while living in disorder. Yet God''s blessings are often sustained through discipline. Create godly routines. Honour your commitments. Live with integrity. Be punctual. Plan wisely. Keep learning. Order is one of the greatest expressions of wisdom because it creates room for God to entrust greater responsibilities. This month, ask the Holy Spirit to rearrange every area of your life that has become disorganized, so that His purposes may flourish through you. Great Grace!', '["Genesis 1:1–31", "Proverbs 24:3–4", "Ecclesiastes 3:1", "James 3:16–18"]'::jsonb, 'Order is the environment where dominion thrives.', 'The wisdom of God establishes divine order in my life. Every area of confusion gives way to clarity. I walk in discipline, excellence, and divine arrangement. My life reflects the order of Heaven, in Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 15, 'Wondersday 15th', 'Fruitful In Every Good Work', 'That ye might walk worthy of the Lord unto all pleasing, being fruitful in every good work, and increasing in the knowledge of God. - Colossians 1:10 KJV', 'God''s desire is not that His children should be fruitful in only one area of life while remaining barren in others. His purpose is comprehensive fruitfulness. A believer should exhibit fruit in character, prayer, ministry, family, relationships, finances, leadership, and service. The Christian life is not compartmentalized. The same Spirit who empowers us to preach also empowers us to love, forgive, lead, create, build, and serve with excellence. This is why Paul prayed that believe rs would be "fruitful in e very good work." True fruitfulness is the outward evidence of an inward transformation. It is impossible to genuinely know God without increasingly reflecting His nature. Fellow Labourer in Christ, do not settle for selective obedience. Allow Christ to influence every dimension of your life. Let your workplace reflect His integrity. Let your home reflect His love. Let your speech reflect His wisdom. Let your decisions reflect His righteousness. The world is waiting for believers whose lives consistently reveal the character of Christ. Remember, your greatest sermon is often not what you say but how you live. As you yield every area of your life to the Holy Spirit, He will make you fruitful beyond your imagination, and your life will become a living testimony of God''s transforming power. Great Grace!', '["John 15:8", "Titus 3:14", "Ephesians 2:10", "Philippians 1:11"]'::jsonb, 'The greatest fruit you can bear is a life that consistently reflects Christ.', 'I am fruitful in every good work. My life glorifies Christ in character, conduct, service, and purpose. I increase continually in the knowledge of God and manifest His nature everywhere I go. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 16, 'Triumphday 16th', 'Subduing Mental Strongholds', 'For the weapons of our warfare are not carnal, but mighty through God to the pulling down of strong holds; Casting down imaginations, and every high thing that exalteth itself against the knowledge of God, and bringing into captivity every thought to the obedience of Christ.” - 2 Corinthians 10:4-5 KJV', 'One of the greatest territories God has commanded every believer to subdue is the mind. Before you can subdue cities, systems, territories, or kingdoms, you must first subdue the thoughts that govern your life. Satan understands that a defeated mind will eventually produce a defeated life, even if the believer possesses great gifts and a powerful anointing. This is why he continually plants seeds of fear, doubt, inferiority, bitterness, lust, unbelief, condemnation, and hopelessness within the mind. These repeated thoughts eventually become strongholds—mental fortresses built by lies that oppose the truth of God''s Word.\n\nEvery stronghold begins with a thought that is entertained, believed, and repeated until it becomes a mindset. However, Genesis 1:28 declares that man was created to subdue, not to be subdued. Through the authority of Christ and the power of God''s Word, every imagination, every argument, and every thought that contradicts God''s purpose must be brought under the Lordship of Jesus Christ. Fellow Labourer in Christ, never allow your mind to become a battlefield where the enemy dictates the outcome.\n\nGuard what you read, what you watch, what you hear, and what you continually meditate upon because your thoughts eventually shape your words, your decisions, your habits, and your destiny. Fill your heart daily with the Scriptures until God''s truth becomes stronger than every negative voice from your past, your environment, or the kingdom of darkness. Refuse to rehearse failure when God has spoken victory. Reject every mindset of limitation when Heaven has declared fruitfulness and dominion over your life. Every day, arrest wrong thoughts before they become wrong beliefs and replace every lie with the truth of God''s Word. A mind governed by the Holy Spirit becomes an unconquerable fortress that no demonic attack can overthrow. When your mind is subdued under Christ, your life will naturally manifest the dominion of Genesis 1:28. Great Grace!', '["Romans 12:2", "Philippians 4:8", "Isaiah 26:3"]'::jsonb, 'You cannot consistently live above the level of your thinking; subdue your mind, and you will subdue your world.', 'I cast down every imagination and every stronghold contrary to the Word of God. My mind belongs to Christ. I reject fear, unbelief, anxiety, inferiority, and every limiting mindset. I think God''s thoughts, I speak God''s Word, and I walk in the dominion of Christ every day. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
