insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 17, 'Faithday 17th', 'The Authority of the Spoken Word', 'Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof. - Proverbs 18:21 KJV', 'From the beginning, God demonstrated that creation responds to spoken authority. Genesis 1 reveals that God did not build the world with His hands; He framed it with His Word. In the same way, man, created in His image, carries the ability to shape realities through words aligned with divine will. Genesis 1:28 begins with “And God said unto them…” showing that destiny is released through spoken instruction and covenant declaration. Words are not empty sounds; they are spiritual containers carrying either life or death, progress or limitation, blessing, or bondage. Fellow Labourer in Christ, guard your mouth diligently, for your future listens to your voice. Many are living below their inheritance, not because God withheld blessings but because their words contradicted His promises. Every time you speak fear, you rei nforce limitation. Every time you speak faith, you activate possibility. Let your speech align with Genesis 1:28 fruitfulness, multiplication, replenishment, subduing, and dominion. Speak life over your family, ministry, health, finances, and calling. Refuse negative confession even when circumstances disagree. The Word of God on your lips becomes the atmosphere in which your destiny grows. Great Grace!', '["James 3:2–6", "Mark 11:23–24", "Isaiah 55:11"]'::jsonb, 'Your life will eventually obey the words you consistently speak.', 'My tongue is an instrument of life. I speak fruitfulness, increase, restoration, and dominion. My words align with God’s purpose, and my destiny responds to my declarations in Christ Jesus. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 18, 'Sabbathday 18th', 'Dominion Over External Influences', 'And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God. - Roman 12:2 KJV', 'One of the greatest expressions of dominion is the ability to remain unmoved by ungodly external influences. The world is constantly attempting to shape the believer through peer pressure, social trends, cultural philosophies, media, and sinful lifestyles. Satan understands that if he cannot destroy your identity, he will attempt to redefine it through the cultures around you. This is why Apostle Paul commands believers not to be conformed to this world. The word "conformed" means to be pr essed into a mould or fashioned according to a pattern. Genesis 1:28 reveals that man was created to exercise dominion over the earth—not to be dominated by it. God''s original design was for man to influence his environment, not for the environment to influence him. Like No ah in a corrupt generation, Joseph in pagan Egypt, Daniel in Babylon, and the three Hebrew boys in a culture of idolatry, believers are called to stand firm in righteousness even when surrounded by compromise. Dominion is not proven when everything around you is holy; it is proven when darkness surrounds you, yet your light refuses to dim. Fellow Labourer in Christ, never permit the standards of society to become the standards of your life. Popular opinion is not the voice of God, and what is celebrated by culture may be condemned by Heaven. You have been called to be a thermostat that changes the atmosphere, not a thermometer that merely reflects it. Refuse the pressure to fit in at the expense of your convictions. Refuse friendships that weaken your consecration, entertainment that pollutes your spirit, conversations that corrupt your faith, and ambitions that draw you away from God''s purpose. The Holy Spirit has empowered you to live differently, think differently, and stand boldly for Christ without apology. As you continually renew your mind with God''s Word and cultivate intimacy with the Holy Spirit, you will develop the spiritual strength to resist every ungodly influence and become a living model of Kingdom culture. This is true dominion, not merely ruling over circumstances, but remaining unshaken in a generation determined to redefine truth. Great Grace!', '["Daniel 1:8", "Psalm 1:1–3", "1 John 2:15–17"]'::jsonb, 'A man who cannot resist the influence of the world cannot effectively exercise dominion in it.', 'I refuse to be conformed to the patterns of this world. I walk in Kingdom culture, and my life reflects the character of Christ. No peer pressure, evil culture, worldly philosophy, or ungodly influence shall derail my destiny. I influence my generation ins tead of being influenced by it. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 19, 'Sacredday 19th', 'Do Not Win Alone', '“Two are better than one; because they have a good reward for their labour. For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up.” - Ecclesiastes 4:9–10 KJV', 'One of the greatest misconceptions about dominion is the belief that success is an individual pursuit. God''s first declaration over mankind was not to one person living in isolation but to humanity as a family. The mandate to "be fruitful, multiply, replenish, subdue, and have dominion" was too vast for one individual to fulfil alone. Kingdom dominion is designed to be collective.\n\nThroughout Scripture, God consistently demonstrates the power of partnership. Noah needed his family to preserve humanity. Moses needed Aaron and Hur to uphold his hands. David had mighty men who helped establish his kingdom. Jesus deliberately chose twelve disciples instead of ministering alone. The early Church transformed the world because believers laboured together in one accord. God''s greatest projects are rarely accomplished by isolated individuals; they are fulfilled through united labourers.\n\nFellow Labourer in Christ, reject the spirit of unhealthy independence. There is a difference between being self-reliant and being Spirit-led. Some opportunities, victories, and dimensions of influence will never manifest until you learn to walk with others in humility, honour, and unity. Do not see every gifted person as a competitor; many are divine partners assigned to strengthen your purpose. Celebrate the grace upon others instead of envying it. Learn to build people, encourage people, and collaborate with people. The Kingdom advances faster when gifted men and women work together. Remember, a victory shared with others produces generational impact, while a victory pursued alone often dies with the individual. Great Grace!', '["Exodus 17:11–13", "Mark 2:1–5", "Acts 2:44–47", "Philippians 1:27"]'::jsonb, 'Great destinies are rarely built alone; they are established through godly partnerships.', 'Father, deliver me from the spirit of isolation. Connect me with covenant, relationships, and faithful labourers. I shall not win alone, but together with those You have ordained, we shall accomplish great exploits for Your Kingdom, in Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 20, 'Mercyday 20th', 'Be a Team Player', 'But now are they many members, yet but one body. And the eye cannot say unto the hand, I have no need of thee….....” - 1 Corinthians 12:20 –21 KJV', 'The human body is one of God''s greatest illustrations of teamwork. Every part is different, yet every part is necessary. The eye sees, but it cannot walk. The feet move, but they cannot hear. The heart pumps blood, but it cannot think. Each member depends upon the others for the body to function effectively. In the same way, the Body of Christ thrives through diversity operating in unity. The dominion mandate of Genesis 1:28 is too comprehensive for one gift, one ministry, or one individual. God intentionally distributes different gifts so that His people will need one another. Where honour exists among diverse graces, extraordinary results become possible. Fellow Labourer in Christ, embrace your place within God''s team. Do not become discouraged because your assignment differs from someone else''s. The Kingdom does not reward imitation; it rewards faithfulness. Your responsibility is not to become another person but to function excellently in the grace God has entrusted to you. Learn to celebrate the victories of others as though they were your own. Refuse jealousy, comparison, and unhealthy competition. Be dependable. Be teachable. Be supportive. The stronges t ministries, families, businesses, and churches are built by people who understand that the success of the whole is greater than the applause of one individual. God is looking for labourers who can work together without striving for personal glory. Great Grace!', '["Romans 12:4–8", "Ephesians 4:11–16", "Philippians 2:1–4", "1 Peter 4:10"]'::jsonb, 'The strength of a team is found in the unity of different gifts.', 'Lord, make me a faithful team player. Deliver me from pride, jealousy, and selfish ambition. Help me to serve with humility, honour every grace You have placed around me, and contribute faithfully to the success of Your Kingdom in Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 21, 'Truthday 21st', 'Dominion Through Coalition', '“How should one chase a thousand, and two put ten thousand to flight, except their Rock had sold them, and the LORD had shut them up?” - Deuteronomy 32:30 KJV', 'One of the greatest mysteries of the Kingdom is the principle of spiritual synergy. God''s mathematics is different from human mathematics. One defeats a thousand, but two defeat ten thousand. The increase is not merely double. It is exponential. This is the power of covenant coalitions. When people are united by God''s purpose rather than personal ambition, Heaven releases multiplied strength, wisdom, favour, and authority. Throughout Scripture, divine coalitions changed history. Joshu a and Caleb stood togeth er in faith. Zerubbabel, Joshua, the high priest, and Haggai rebuilt the Temple. Paul worked with Barnabas, Silas, Timothy, Titus, Aquila, and Priscilla to establish churches across nations. The Kingdom expands most effectively when anointed people unite around a common vision. Fellow Labourer in Christ, pray for discernment to recognize your kingdom alliances. Not every relationship is covenant, but every destiny requires covenant relationships. God places strategic people in our lives to sharpen us, strengthen us, correct us, a nd help us fulfil our assignments. Never allow pride to destroy divine partnerships. Protect unity. Honour loyalty. Invest in relationships that advance God''s purpose. A healthy coalition does not weaken your identity; it strengthens your effectiveness. As you build and maintain godly alliances, you will accomplish exploits that would have been impossible alone. Together, the Church demonstrates the fullness of Christ and establishes His dominion upon the earth. Great Grace!', '["Amos 3:3", "Ecclesiastes 4:9–12", "Acts 13:1–3", "Hebrews 10:24–25"]'::jsonb, 'Kingdom coalitions produce exponential dominion where isolated effort produces limited results.', 'Father, surround me with covenant relationships and divine coalitions that advance your purpose. I receive wisdom to build, preserve, and honour kingdom partnerships. Together, we shall establish Your dominion and fulfil our divine assignments in Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 22, 'Wondersday 22nd', 'Little Drops Make an Ocean', 'For whom hath despised the day of small things? for they shall rejoice and shall see the plummet in the hand of Zerubbabel with those seven; they are the eyes of the LORD, which run to and fro through the whole earth.” - Zechariah 4:10 KJV ne of the greatest enemies of fruitfulness is the inability to appreciate small beginnings. God rarely begins with abundance; He often begins with a seed. The oak tree begins as an acorn, mighty rivers begin as tiny streams, and oceans are formed by countless drops of water. The Kingdom of God follows the same principle. Every great ministry, every successful business, every influential leader, and every extraordinary testimony once existed in a small, almost unnoticed form. Genesis 1:28 commands us to be f ruitful before multiplying because God first blesses what is small before He enlarges it. Those who continually complain about little blessings often delay the arrival of greater ones because gratitude is the language that attracts increase. Heaven entrust s much to those who honour little. When you celebrate one answered prayer, one open door, one soul won, one faithful friend, one opportunity, or one lesson learned, you are acknowledging that God is already at work in your life. Fellow Labourer in Christ, learn to celebrate every drop while believing for the ocean. Do not postpone your joy until the breakthrough becomes massive. Thank God for today''s strength while expecting tomorrow''s promotion. Rejoice over the little business t hat is growing, the small congregation that is increasing, the modest salary that feeds your family, the few opportunities that God has opened, and the little victories won in secret. Many people miss miracles because they are too occupied looking for spec tacular manifestations. Yet God''s greatest works often begin quietly. Gratitude transforms ordinary moments into sacred encounters. As you faithfully appreciate every little blessing, God will combine them into an overflowing testimony that generations will admire. Great Grace!', 'O', '["Luke 16:10", "Matthew 13:31–32", "Psalm 92:1–2", "1 Thessalonians 5:18"]'::jsonb, 'Those who honour little blessings qualify for greater ones.', 'I refuse to despise the day of small beginnings. I receive a grateful heart. Every little blessing in my life shall grow into extraordinary abundance. I celebrate every drop because I know God is preparing my ocean. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 23, 'Triumphday 23rd', 'The Grace of Compound Interest', 'Whatsoever thy hand findeth to do, do it with thy might...” - Ecclesiastes 9:10 KJV', 'One of God''s hidden laws for multiplication is the principle of consistent accumulation. In the financial world, compound interest causes small investments made consistently to become extraordinary wealth over time. The Kingdom of God operates in a similar way. Every prayer, every page of Scripture studied, every act of obedience, every soul won, every seed sown, every sacrifice made, every discipline embraced, and every day spent walking faithfully with God is never wasted. They accumulate in the spirit until they suddenly produce uncommon results. People often admire overnight success without realizing that Heaven has been adding unseen deposits for years. Noah built the ark one plank at a time. Joseph interpreted dreams faithfully before ruling Egypt. Davi d fought lions and bears before confronting Goliath. Their greatness was the product of accumulated obedience. Fellow Labourer in Christ, never underestimate the power of consistency. One prayer may seem insignificant, but ten thousand prayers create spiritual authority. One chapter of Scripture each day may appear small, but years of consistent study produce profound wisdom. One act of kindness may seem unnoticed, but repeated acts build a godly reputation. One day of discipline may appear ordinary, but disciplined years create extraordinary people. Continue adding daily deposits into your spiritual, intellectual, emotional, and financial life. The God of Genesis 1:28 delights in multiplication, and multiplication often comes through accumulated faithfulness rather than isolated moments of excitement. Keep sowing. Keep serving. Keep growing your compound harvest is closer than you think. Great Grace!', '["Galatians 6:9", "Hebrews 6:10", "Proverbs 13:11", "1 Corinthians 15:58"]'::jsonb, 'Consistency is the compound interest of destiny.', 'Every act of obedience accumulates into greatness. I receive grace for consistency. My daily investments in God shall produce extraordinary harvests. Nothing I do for Christ shall ever be wasted. Glory.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 24, 'Faithday 24th', 'Maintain The Quality Of Your Efforts', 'And whatsoever ye do, do it heartily, as to the Lord, and not unto men.” - Colossians 3:23 KJV', 'One of the subtle dangers that accompanies success is complacency. Many people pray fervently until God begins to bless them, but once testimonies become frequent, the quality of their effort begins to decline. They pray less, prepare less, study less, work less diligently, and become comfortable with yesterday''s victories. Yet the blessing of Genesis 1:28 was never intended to replace diligence; it was meant to empower it. God blesses excellence, consistency, and faithful stewardship. The same discipline that brought yesterday''s breakthrough is often required to sustain tomorrow''s increase. Harvest should never become an excuse to abandon cultivation. Fellow Labourer in Christ, never allow yesterday''s testimony to reduce today''s commitment. Continue praying with intensity. Continue studying with hunger. Continue preparing with excellence. Continue serving with humility. Continue giving your best even when people already celebrate you. Great men do not become great by occasional excellence but by maintaining high standards long after success has arrived. Remember that God watches not only beginnings but continuations. Your yield will always correspond to the quality of your cultivation. Therefore, refuse mediocrity. Refuse carelessness. Let every assignment, sermon, business transaction, conversation, and act of service reflect your best because you are ultimately serving the Lord. Great Grace!', '["Proverbs 22:29", "Ecclesiastes 9:10", "2 Timothy 2:15", "Matthew 25:21"]'::jsonb, 'What produced the harvest must be maintained to preserve the harvest.', 'I receive grace to maintain excellence. Success shall not make me careless, and testimonies shall not reduce my diligence. I shall continually give God my best in every assignment. Hallelujah.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 25, 'Sabbathday 25th', 'A Personality That Reflects The Blessing', 'A good name is rather to be chosen than great riches and loving favour rather than silver and gold.” - Proverbs 22:1 KJV', 'God''s blessing is not revealed only in what we possess but also in who we become. A truly blessed person should carry a personality that reflects the character of Christ. The blessing of Genesis 1:28 was given so that man would represent God on the earth, and representation begins with character before it reaches achievement. A harsh, arrogant, unapproachable, and dishonourable attitude contradicts the very nature of the God we claim to represent. Jesus possessed all authority in Heaven and on earth, yet He was approachable by children, compassionate toward sinners, patient with the weak, and gracious to the broken. Greatness in the Kingdom is measured not merely by influence but by the quality of one''s character. Fellow Labourer in Christ, let your personality become an advertisement of God''s goodness. Be warm in your greetings, sincere in your appreciation, gracious in your speech, approachable in your attitude, generous with encouragement, patient with people''s weaknesses, and humble despite your achievements. Let people encounter peace when they meet you. Let your smile restore hope, your words inspire courage, and your conduct reveal Christ. Never become so important that you forget kindness. Never become so suc cessful that you become inaccessible. The blessing of God should beautify your character as much as it enlarges your possessions. A beautiful personality opens doors that money, intelligence, and influence cannot open. May your life continually reflect the fragrance of Christ wherever you go. Great Grace!', '["Philippians 2:3 –5", "Colossians 4:6", "Ephesians 4:29 –32", "Matthew 11:29"]'::jsonb, 'Your character is the fragrance of the blessing you carry.', 'My life reflects the beauty of Christ. I am humble, gracious, joyful, approachable, compassionate, and full of wisdom. My personality attracts favour because it reveals the nature of my Father. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 26, 'Sacredday 26th', 'Hating Me Is Not Enough', '‘… So the wall was finished... And it came to pass, that when all our enemies heard thereof... they were much cast down in their own eyes: for they perceived that this work was wrought of our God.’ - Nehemiah6:15-16 KJV', 'One of the greatest misconceptions believers have is that opposition is proof that they have missed God. On the contrary, genuine Kingdom advancement often attracts resistance. The life of Nehemiah demonstrates that God''s assignment does not eliminate enemies; it exposes them. Sanballat, Tobiah, Geshem, and their allies mocked, threatened, lied, conspired, and attempted to distract Nehemiah from rebuilding Jerusalem''s walls. Yet every attack only amplified God''s glory because the opposition became undeniable evidence that the work was ordained by Heaven. The enemies unintentionally advertised Nehemiah''s relevance. If there had been nothing significant about his assignment, no one would have wasted time opposing him. This reveals a profound Kingdom mystery: ha tred cannot cancel what God has blessed. Genesis 1:28 begins with God''s blessing, and once God blesses a man, human hostility loses the power to reverse divine purpose. In fact, many times God uses opposition as the platform upon which He publicly reveals His power. Fellow Labourer in Christ, never become discouraged because of critics, envy, betrayal, or opposition. There are people whose assignment is to resist you, but even they remain servants of God''s sovereign purpose. Joseph''s brothers hated him, yet their hatr ed transported him to Egypt where his destiny awaited him. Pharaoh''s oppression multiplied Israel. Saul''s jealousy prepared David for the throne. The cross, designed to destroy Jesus, became the instrument of humanity''s redemption. This is why you must never spend your energy fighting haters. Stay focused on your assignment. Build while they criticize. Pray while they accuse. Advance while they conspire. Those who attempt to stop what God is doing in your life will eventually become witnesses of your testim ony. Remember this: haters cannot stop a man who is carrying the blessing of Genesis 1:28; they merely become unwilling participants in the fulfilment of his destiny. Great Grace!', '["Nehemiah 4:1–20", "Nehemiah 6:1–16", "Genesis 50:20", "Romans 8:28"]'::jsonb, 'When God blesses a man, even his enemies unknowingly contribute to his destiny.', 'The blessing of God upon my life cannot be reversed by the hatred of men. Every opposition works together for my advancement. I remain focused on my divine assignment, and every conspiracy against me shall ultimately glorify God. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
