insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 27, 'Mercyday 27th', 'Influencing Palaces', 'Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men. - Proverbs 22:29 KJV', 'God never intended His people to remain confined within church buildings. The dominion mandate of Genesis 1:28 extends into governments, boardrooms, royal courts, educational institutions, media, business, and every sphere where decisions shaping generations are made. Throughout Scripture, God consistently positioned His servants inside palaces. Joseph stood before Pharaoh and preserved nations. Daniel interpreted dreams before Nebuchadnezzar and Darius. Esther influenced the thro ne of Persia and rescued an entire people. Moses confronted Pharaoh with the authority of Heaven. Paul testified before governors, kings, and Caesar''s representatives. Their assignment was never merely to occupy positions but to bring Heaven''s culture into earthly governments. God ra ises Kingdom ambassadors who can speak truth without compromise and demonstrate excellence without losing consecration. Fellow Labourer in Christ, never underestimate where God is taking you. The excellence you cultivate today may become your passport into tomorrow''s palace. But remember, palaces are not destinations —they are platforms for Kingdom influence. If God places y ou before influential people, it is not merely for personal promotion but for divine representation. Let your wisdom reveal Christ. Let your integrity preach louder than your words. Let your solutions glorify God. Never hide your faith to gain acceptance, neither should you become arrogant because of influence. Carry the presence of God into every room you enter. The greatest victory is not merely entering the palace; it is ensuring that the King of kings is represented inside the palace through your life. Great Grace!', '["Daniel 2:46–49", "Esther 4:13–16", "Genesis 41:37–44", "Acts 26:1–29"]'::jsonb, 'God promotes His people into palaces so His Kingdom can influence kingdoms.', 'God opens doors that no man can shut. I stand before kings, leaders, and influential people as an ambassador of Christ. Through my life, God''s wisdom, righteousness, and Kingdom are established in high places. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
