insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 28, 'Truthday 28th', 'Leveraging The Gift Of Men', '‘Two are better than one; because they have a good reward for their labour. For if they fall, the one will lift up his fellow…’ - Ecclesiastes 4:9 - 10 KJV', 'One of God''s greatest gifts to destiny is people. While every believer must depend ultimately on God, God frequently chooses to answer prayers through human vessels. The dominion mandate in Genesis 1:28 was never designed to be fulfilled in isolation. Throughout Scripture, God connected people to people in order to advance His purposes. Moses had Aaron and Hur. David had Jonathan and his mighty men. Ruth had Boaz. Paul had Barnabas, Silas, Timothy, and Luke. Jesus Himself surrounded His ministry with disciples. Divine relationships are not accidents; they are strategic Kingdom provisions. Many doors do not open because of what you know alone, but because of who God has connected you to. There are dimensions of dominion that are unlocked through covenant relat ionships, wise counsel, mentorship, partnerships, and favour with men whom God has strategically positioned along your path. Fellow Labourer in Christ, never become so independent that you reject the gift of people. Honour those whom God sends into your life. Learn from mentors. Value spiritual fathers. Appreciate destiny helpers. Build relationships with integrity rather than m anipulation. Remember that favour cannot be demanded; it is attracted through character, humility, faithfulness, and excellence. Do not burn bridges that God may use tomorrow. Pray for discernment to recognize the people God has ordained for your next seas on, and equally strive to become a blessing in the lives of others. Sometimes your next level is not waiting for another miracle, it is waiting for the right relationship. When God blesses a man, He often sends another man carrying the key to his next door. Great Grace!', '["1 Samuel 18:1 –4", "Exodus 17:11 –13", "Romans 16:1 –16", "Philippians 2:19–22"]'::jsonb, 'God often hides your next level inside the life of another person.', 'Father, connect me with every relationship ordained for my destiny. I receive the gift of godly mentors, faithful partners, and divine helpers. Through covenant relationships, I fulfil my assignment and walk in dominion according to Your purpose. In Jesus'' Name. Amen.'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 29, 'Wondersday 29th', 'The Lane Of Competition', '“But let every man prove his own work, and then shall he have rejoicing in himself alone, and not in another.” - Galatians 6:4 KJV', 'One of the most subtle destroyers of destiny is the spirit of comparison. It quietly shifts a believer from purpose to performance, from assignment to rivalry, and from divine assignment to human competition. Genesis 1:28 never called man to compete; it called man to be fruitful. Fruitfulness is identity -driven, not comparison-driven. The moment a believer begins to measure his life by another man’s field, speed, or results, he steps into a lane God never assigned to him. In the Kingdom, grace is distributed differently; assignments are unique, and timing is divine. What looks like delay may simply be alignment, and what looks like speed may not be covenant depth. God does not evaluate destinies by comparison but by obedience and faithfulness. Fellow Labourer in Christ, refuse to enter the toxic lane of competition. It drains joy, distorts purpose, and blinds you to your own progress. You are not in a race against men—you are in a walk with God. Your assignment carries its own grace, its own timing, and its own harvest. Celebrate others without feeling threatened; learn without envy; grow without comparison. Focus on your field, your instruction, and your stewardship. The day you master contentment in your assignment; you step into accelerated grace. Heaven does not reward comparison; it rewards faithfulness. Great Grace!', '["2 Corinthians 10:12", "John 21:21 –22", "Romans 12:6", "Philippians 4:11–13"]'::jsonb, 'Comparison is the thief of divine focus and gratitude.', 'I reject the spirit of comparison. I walk in my God -given assignment with joy and clarity. My life is not measured by others but by divine faithfulness. I flourish in my own grace and timing, in Jesus’ Name. Amen!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
  wisdom_nugget = excluded.wisdom_nugget, declaration = excluded.declaration;
insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 30, 'Triumphday 30th', 'Subdue Systems, Not Men', '“For we wrestle not against flesh and blood, but against principalities, against powers…” - Ephesians 6:12 KJV', 'True dominion in Genesis 1:28 was never designed to be exercised over human beings but over systems, structures, and spiritual influences that resist God’s order. Man’s fall distorted dominion, causing men to dominate one another instead of governing creation under God. But in redemption, Christ restores correct authority; believers are called to subdue systems of darkness, not people created in God’s image. Systems include patterns of corruption, cycles of limitation, spiritual strongholds, cultural bondage, and environmental oppression. These are what resist destiny, not men. When a believer misidentifies the real enemy, he fights the wrong battles and loses spiritual authority. Fellow Labourer in Christ, shift your focus from human opposition to spiritual systems. Do not waste divine energy fighting people; learn to discern what spirit or system is influencing situations. The believer’s authority is most powerful when correctly directed. Through prayer, wisdom, and obedience, you dismantle systems of failure, delay, sin, and oppression. This is why Christ never attacked men. He confronted systems. As you grow in spiritual maturity, your prayers become strategic, your decisions bec ome precise, and your influence becomes transformational. Dominion is not control over people; it is transformation of environments under God’s authority. Great Grace!', '["Ephesians 6:12", "2 Corinthians 10:3 –5", "Luke 10:19", "Colossians 2:15"]'::jsonb, 'Mature dominion confronts systems, not people.', 'I subdue systems of darkness and resistance in the name of Jesus. I do not fight men; I enforce God’s order over structures and spiritual influences. My authority brings transformation and peace. Amen!'
on conflict (edition_id, day_number) do update set
  weekday = excluded.weekday, title = excluded.title, scripture_reference = excluded.scripture_reference,
  meditation = excluded.meditation, further_studies = excluded.further_studies,
