insert into public.devotions (edition_id, day_number, weekday, title, scripture_reference, meditation, further_studies, wisdom_nugget, declaration)
select (select id from public.editions where slug = 'shiloh-july-2026'), 31, 'Faithday 31 st', 'For The Kingdom, For The Church', '“But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.” - Matthew 6:33 KJV', 'Genesis 1:28 reveals a blessed man, but Matthew 6:33 reveals the priority of that blessing, Kingdom advancement. The blessing upon a believer is never meant for self-glorification but for Kingdom expansion and Church edification. God blesses His people so that His purposes can be established in the earth. When the heart is aligned with the Kingdom, personal increase becomes a by-product of divine assignment. The Church is God’s visible expression on earth, and every believer is called to contribute to its gr owth through prayer, service, giving, and influence. Kingdom-centred living ensures that blessing flows through a man, not just to a man. Fellow Labourer in Christ, let your desire for increase be connected to Kingdom impact. Ask God to bless you not for vanity, but so you can strengthen His work, expand His Church, and advance His purpose in your generation. A Kingdom-focused life is a fruitful life. When your priorities align with God’s house, God aligns His hand with your life. Seek first His Kingdom, and watch Him establish your personal matters beyond struggle. This is the mystery of divine order —God prospers those who carry His agenda. Let your life become a channel of blessing to the Church worldwide, and your testimony will overflow with grace. Great Grace!', '["Matthew 6:33", "Haggai 1:8", "Acts 2:47", "Philippians 1:5"]'::jsonb, 'Kingdom priority transforms personal blessing into global impact.', 'I am blessed for Kingdom purpose. My life advances the Church of Jesus Christ. I prosper to support God’s work, and my increase serves eternal purposes. Amen.'
